/usr/bin/bash -lc "python - <<'PY'
import json, pathlib, collections
s=collections.Counter()
for p in pathlib.Path('data/orders').glob('*'):
    if p.is_file():
        o=json.loads(p.read_text())
        if o['status']=='paid':
            s[o['customer']] += sum(i['qty']*i['unitPriceCents'] for i in o['items'])
for name, cents in s.most_common(): print(name, cents)
PY"

